CREATE OR REPLACE FUNCTION private.blink_boost_assert_owned_target(p_user uuid, p_target_type text, p_target_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    if p_user is null then raise exception 'AUTH_REQUIRED'; end if;
    if p_target_id is null then raise exception 'BOOST_TARGET_REQUIRED'; end if;

    case upper(coalesce(p_target_type,''))
        when 'POST' then
            if not exists (
                select 1 from public.feed_posts p
                where p.id=p_target_id and p.user_id=p_user
                  and p.is_active=true and coalesce(p.is_reel,false)=false
            ) then raise exception 'BOOST_POST_NOT_AVAILABLE'; end if;
        when 'REEL' then
            if not exists (
                select 1 from public.feed_posts p
                where p.id=p_target_id and p.user_id=p_user
                  and p.is_active=true and coalesce(p.is_reel,false)=true
            ) then raise exception 'BOOST_REEL_NOT_AVAILABLE'; end if;
        when 'PROFILE' then
            if p_target_id<>p_user or not exists(select 1 from public.profiles p where p.id=p_user) then
                raise exception 'BOOST_PROFILE_NOT_AVAILABLE';
            end if;
        when 'LISTING' then
            if not exists (
                select 1 from public.market_items m
                where m.id=p_target_id and m.seller_id=p_user and coalesce(m.is_sold,false)=false
            ) then raise exception 'BOOST_LISTING_NOT_AVAILABLE'; end if;
        else
            raise exception 'INVALID_BOOST_TARGET_TYPE';
    end case;
end;
$function$

CREATE OR REPLACE FUNCTION private.blink_boost_quote(p_target_type text, p_boost_power integer, p_objective text, p_audience_scope text, p_duration_days integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_type text := upper(coalesce(p_target_type,''));
    v_objective text := upper(coalesce(p_objective,''));
    v_audience text := upper(coalesce(p_audience_scope,''));
    v_base numeric;
    v_objective_bps numeric;
    v_audience_bps numeric;
    v_duration_bps numeric;
    v_minimum numeric;
    v_cost bigint;
    v_reach_low bigint;
    v_reach_high bigint;
    v_low_base numeric;
    v_high_base numeric;
begin
    if p_boost_power not between 1 and 100 then raise exception 'INVALID_BOOST_POWER'; end if;
    if p_duration_days not in (1,3,7,14,30) then raise exception 'INVALID_BOOST_DURATION'; end if;

    v_base := case v_type
        when 'POST' then private.blink_boost_growth_number('post_base_daily',900)
        when 'REEL' then private.blink_boost_growth_number('reel_base_daily',1100)
        when 'PROFILE' then private.blink_boost_growth_number('profile_base_daily',800)
        when 'LISTING' then private.blink_boost_growth_number('listing_base_daily',1000)
        else null end;
    if v_base is null then raise exception 'INVALID_BOOST_TARGET_TYPE'; end if;

    v_objective_bps := case v_objective
        when 'REACH' then private.blink_boost_growth_number('objective_reach_bps',10000)
        when 'VIEWS' then private.blink_boost_growth_number('objective_views_bps',10000)
        when 'LIKES' then private.blink_boost_growth_number('objective_likes_bps',11500)
        when 'SAVES' then private.blink_boost_growth_number('objective_saves_bps',12000)
        when 'PROFILE_VISITS' then private.blink_boost_growth_number('objective_profile_visits_bps',11500)
        when 'ENGAGEMENT' then private.blink_boost_growth_number('objective_engagement_bps',12500)
        when 'COMMENTS' then private.blink_boost_growth_number('objective_comments_bps',13000)
        when 'FOLLOWERS' then private.blink_boost_growth_number('objective_followers_bps',13000)
        when 'BUYER_INTEREST' then private.blink_boost_growth_number('objective_buyer_interest_bps',14000)
        else null end;
    if v_objective_bps is null then raise exception 'INVALID_BOOST_OBJECTIVE'; end if;

    v_audience_bps := case v_audience
        when 'MY_UNIVERSITY' then private.blink_boost_growth_number('audience_my_university_bps',10000)
        when 'SELECTED_UNIVERSITY' then private.blink_boost_growth_number('audience_selected_university_bps',11000)
        when 'ALL_CAMPUSES' then private.blink_boost_growth_number('audience_all_campuses_bps',16000)
        else null end;
    if v_audience_bps is null then raise exception 'INVALID_BOOST_AUDIENCE'; end if;

    v_duration_bps := private.blink_boost_growth_number(
        'duration_'||p_duration_days::text||'_bps',
        10000
    );
    v_minimum := private.blink_boost_growth_number('minimum_campaign_coins',50);

    v_cost := greatest(
        v_minimum,
        ceil(
            v_base
            * p_boost_power::numeric / 100
            * v_objective_bps / 10000
            * v_audience_bps / 10000
            * p_duration_days
            * v_duration_bps / 10000
        )
    )::bigint;

    v_low_base := private.blink_boost_growth_number(lower(v_type)||'_reach_low_per_day',400);
    v_high_base := private.blink_boost_growth_number(lower(v_type)||'_reach_high_per_day',800);
    v_reach_low := greatest(1,ceil(v_low_base*p_boost_power::numeric/100*p_duration_days*v_audience_bps/10000))::bigint;
    v_reach_high := greatest(v_reach_low,ceil(v_high_base*p_boost_power::numeric/100*p_duration_days*v_audience_bps/10000))::bigint;

    return jsonb_build_object(
        'target_type',v_type,
        'boost_power',p_boost_power,
        'objective',v_objective,
        'audience_scope',v_audience,
        'duration_days',p_duration_days,
        'coin_cost',v_cost,
        'estimated_reach_low',v_reach_low,
        'estimated_reach_high',v_reach_high,
        'estimate_only',true
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_blink_boost_campaign(p_target_type text, p_target_id uuid, p_boost_power integer, p_objective text, p_audience_scope text, p_duration_days integer, p_target_university text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_user uuid := auth.uid();
    v_quote jsonb;
    v_cost bigint;
    v_balance numeric;
    v_campaign public.blink_boost_campaigns_v2%rowtype;
    v_university text;
begin
    if v_user is null then raise exception 'AUTH_REQUIRED'; end if;

    v_quote := public.quote_blink_boost_campaign(
        p_target_type,p_target_id,p_boost_power,p_objective,
        p_audience_scope,p_duration_days,p_target_university
    );
    v_cost := (v_quote->>'coin_cost')::bigint;
    v_university := nullif(v_quote->>'target_university','');

    insert into public.user_balances(user_id,spendable_coin_balance,updated_at)
    values(v_user,0,now())
    on conflict(user_id) do nothing;

    select b.spendable_coin_balance into v_balance
    from public.user_balances b
    where b.user_id=v_user
    for update;

    if coalesce(v_balance,0)<v_cost then raise exception 'INSUFFICIENT_BLINK_COINS'; end if;

    update public.user_balances
       set spendable_coin_balance=spendable_coin_balance-v_cost,
           updated_at=now()
     where user_id=v_user
    returning spendable_coin_balance into v_balance;

    insert into public.blink_boost_campaigns_v2(
        user_id,target_type,target_id,objective,boost_power,
        audience_scope,target_university,duration_days,coin_budget,
        estimated_reach_low,estimated_reach_high,starts_at,ends_at
    ) values (
        v_user,
        upper(p_target_type),
        p_target_id,
        upper(p_objective),
        p_boost_power,
        upper(p_audience_scope),
        v_university,
        p_duration_days,
        v_cost,
        (v_quote->>'estimated_reach_low')::bigint,
        (v_quote->>'estimated_reach_high')::bigint,
        now(),
        now()+make_interval(days=>p_duration_days)
    )
    returning * into v_campaign;

    insert into public.blink_coin_transactions(
        user_id,kind,catalog_id,item_name,amount,balance_after,metadata
    ) values (
        v_user,
        'BOOST_CAMPAIGN_RESERVE',
        null,
        'Boost '||initcap(lower(v_campaign.target_type)),
        -v_cost,
        floor(v_balance)::bigint,
        jsonb_build_object(
            'campaign_id',v_campaign.id,
            'target_type',v_campaign.target_type,
            'target_id',v_campaign.target_id,
            'boost_power',v_campaign.boost_power,
            'objective',v_campaign.objective,
            'audience_scope',v_campaign.audience_scope,
            'duration_days',v_campaign.duration_days
        )
    );

    return jsonb_build_object(
        'success',true,
        'campaign_id',v_campaign.id,
        'reserved',v_cost,
        'charged',v_cost,
        'balance',floor(v_balance)::bigint,
        'campaign',to_jsonb(v_campaign),
        'quote',v_quote
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_blink_drop(p_target_type text, p_target_id uuid, p_action text, p_reward_per_user integer, p_winner_count integer, p_audience_scope text, p_duration_hours integer DEFAULT 24)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := auth.uid();
  v_target_type text := upper(btrim(coalesce(p_target_type,'')));
  v_action text := upper(btrim(coalesce(p_action,'')));
  v_scope text := upper(btrim(coalesce(p_audience_scope,'')));
  v_university text;
  v_budget bigint;
  v_balance numeric;
  v_drop public.blink_drops%rowtype;
  v_eligible integer := 0;
begin
  if v_user is null then raise exception 'AUTH_REQUIRED'; end if;
  perform private.blink_drop_expire_stale();

  if p_reward_per_user < 100
     or p_reward_per_user > 100000
     or p_reward_per_user % 100 <> 0 then
    raise exception 'DROP_REWARD_INVALID';
  end if;
  if p_winner_count < 1 or p_winner_count > 500 then
    raise exception 'DROP_WINNER_COUNT_INVALID';
  end if;
  v_budget := p_reward_per_user::bigint * p_winner_count::bigint;
  if v_budget > 10000000 then raise exception 'DROP_BUDGET_TOO_LARGE'; end if;
  if p_duration_hours not in (1,6,12,24,72,168) then
    raise exception 'DROP_DURATION_INVALID';
  end if;

  if not private.blink_drop_target_owned(v_user,v_target_type,p_target_id) then
    raise exception 'DROP_TARGET_NOT_OWNED';
  end if;

  if v_target_type in ('POST','REEL') and v_action not in ('LIKE','COMMENT','REPOST') then
    raise exception 'DROP_ACTION_INVALID';
  elsif v_target_type='LISTING' and v_action<>'SAVE_LISTING' then
    raise exception 'DROP_ACTION_INVALID';
  end if;

  if v_scope='MY_CAMPUS' then
    select nullif(btrim(coalesce(p.university,'')),'')
      into v_university
    from public.profiles p where p.id=v_user;
    if v_university is null then raise exception 'UNIVERSITY_REQUIRED_FOR_DROP'; end if;
  elsif v_scope='ALL_CAMPUSES' then
    v_university := null;
  else
    raise exception 'DROP_AUDIENCE_INVALID';
  end if;

  insert into public.user_balances(user_id,spendable_coin_balance,updated_at)
  values(v_user,0,now())
  on conflict(user_id) do nothing;

  select b.spendable_coin_balance into v_balance
  from public.user_balances b
  where b.user_id=v_user
  for update;

  if coalesce(v_balance,0)<v_budget then raise exception 'INSUFFICIENT_BLINK_COINS'; end if;

  update public.user_balances
  set spendable_coin_balance=spendable_coin_balance-v_budget,
      updated_at=now()
  where user_id=v_user
  returning spendable_coin_balance into v_balance;

  insert into public.blink_drops(
    creator_id,target_type,target_id,action,reward_per_user,winner_count,
    audience_scope,target_university,total_budget,starts_at,ends_at
  ) values (
    v_user,v_target_type,p_target_id,v_action,p_reward_per_user,p_winner_count,
    v_scope,v_university,v_budget,now(),now()+make_interval(hours=>p_duration_hours)
  )
  returning * into v_drop;

  insert into public.blink_coin_transactions(
    user_id,kind,catalog_id,item_name,amount,balance_after,metadata
  ) values (
    v_user,
    'DROP_RESERVE',
    null,
    'BLINK Drop reserve',
    -v_budget,
    floor(v_balance)::bigint,
    jsonb_build_object(
      'drop_id',v_drop.id,
      'target_type',v_target_type,
      'target_id',p_target_id,
      'action',v_action,
      'reward_per_user',p_reward_per_user,
      'winner_count',p_winner_count,
      'audience_scope',v_scope
    )
  );

  insert into public.blink_drop_eligible_followers(drop_id,user_id)
  select v_drop.id,f.follower_id
  from public.follows f
  join public.profiles recipient on recipient.id=f.follower_id
  where f.following_id=v_user
    and f.follower_id<>v_user
    and (
      v_scope='ALL_CAMPUSES'
      or lower(coalesce(recipient.university,''))=lower(coalesce(v_university,''))
    )
    and not exists (
      select 1 from public.blocks b
      where (b.blocker_id=v_user and b.blocked_id=f.follower_id)
         or (b.blocker_id=f.follower_id and b.blocked_id=v_user)
    )
  on conflict do nothing;

  get diagnostics v_eligible = row_count;

  insert into public.notifications(
    user_id,actor_id,type,target_type,target_id,text,sub_text,is_read,metadata
  )
  select
    e.user_id,
    v_user,
    'system'::public.notification_type_enum,
    'giveaway',
    v_drop.id,
    'started a BLINK Drop',
    p_reward_per_user::text || ' coins each · ' ||
      initcap(lower(replace(v_action,'_',' '))) || ' · ' ||
      p_winner_count::text || ' rewards',
    false,
    jsonb_build_object(
      'drop_id',v_drop.id,
      'reward_per_user',p_reward_per_user,
      'winner_count',p_winner_count,
      'action',v_action,
      'target_type',v_target_type
    )
  from public.blink_drop_eligible_followers e
  where e.drop_id=v_drop.id;

  return jsonb_build_object(
    'success',true,
    'drop_id',v_drop.id,
    'reserved',v_budget,
    'balance',floor(v_balance)::bigint,
    'eligible_followers',v_eligible,
    'ends_at',v_drop.ends_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_blink_boost_growth_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_user uuid := auth.uid();
    v_balance bigint := 0;
    v_campaigns jsonb;
begin
    if v_user is null then raise exception 'AUTH_REQUIRED'; end if;
    perform private.settle_blink_boost_campaigns(v_user);

    select coalesce(floor(b.spendable_coin_balance),0)::bigint into v_balance
    from public.user_balances b where b.user_id=v_user;

    v_campaigns:=public.get_my_blink_boost_campaigns();

    return jsonb_build_object(
        'balance',coalesce(v_balance,0),
        'pricing',jsonb_build_object(
            'post_base_daily',private.blink_boost_growth_number('post_base_daily',900),
            'reel_base_daily',private.blink_boost_growth_number('reel_base_daily',1100),
            'profile_base_daily',private.blink_boost_growth_number('profile_base_daily',800),
            'listing_base_daily',private.blink_boost_growth_number('listing_base_daily',1000),
            'minimum_campaign_coins',private.blink_boost_growth_number('minimum_campaign_coins',50)
        ),
        'mission_daily_suggested_points',private.blink_boost_growth_number('mission_daily_suggested_points',20),
        'campaigns',coalesce(v_campaigns->'items','[]'::jsonb),
        'organic_ranking_separate',true
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.quote_blink_boost_campaign(p_target_type text, p_target_id uuid, p_boost_power integer, p_objective text, p_audience_scope text, p_duration_days integer, p_target_university text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_user uuid := auth.uid();
    v_scope text := upper(coalesce(p_audience_scope,''));
    v_university text;
    v_quote jsonb;
begin
    if v_user is null then raise exception 'AUTH_REQUIRED'; end if;
    perform private.blink_boost_assert_owned_target(v_user,p_target_type,p_target_id);

    if v_scope='MY_UNIVERSITY' then
        select nullif(btrim(coalesce(p.university,'')),'') into v_university
        from public.profiles p where p.id=v_user;
        if v_university is null then raise exception 'UNIVERSITY_REQUIRED_FOR_BOOST'; end if;
    elsif v_scope='SELECTED_UNIVERSITY' then
        v_university := nullif(btrim(coalesce(p_target_university,'')),'');
        if v_university is null then raise exception 'BOOST_TARGET_UNIVERSITY_REQUIRED'; end if;
    elsif v_scope='ALL_CAMPUSES' then
        v_university := null;
    else
        raise exception 'INVALID_BOOST_AUDIENCE';
    end if;

    v_quote := private.blink_boost_quote(
        p_target_type,p_boost_power,p_objective,v_scope,p_duration_days
    );
    return v_quote || jsonb_build_object(
        'target_id',p_target_id,
        'target_university',v_university
    );
end;
$function$

CREATE OR REPLACE FUNCTION private.expire_blink_items_and_remind_vip()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ begin
 update public.blink_inventory set status='EXPIRED',updated_at=now() where status='ACTIVE' and expires_at is not null and expires_at<=now();
 update public.blink_boosts set status='ENDED' where status='ACTIVE' and ends_at<=now();
 insert into public.notifications(user_id,type,comment) select v.user_id,'system','👑 Your Blink VIP expires in less than 24 hours. Open Blink Store to review or renew.' from public.blink_vip_passes v where v.expires_at>now() and v.expires_at<=now()+interval '24 hours' and not v.expiry_reminder_sent;
 update public.blink_vip_passes set expiry_reminder_sent=true where expires_at>now() and expires_at<=now()+interval '24 hours' and not expiry_reminder_sent;
 update public.profiles p set blink_vip_until=(select max(v.expires_at) from public.blink_vip_passes v where v.user_id=p.id and v.expires_at>now()) where p.blink_vip_until is not null and p.blink_vip_until<=now();
end $function$

CREATE OR REPLACE FUNCTION private.process_blink_vip_auto_renewals()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare r record; v_price integer:=350; v_balance bigint; v_pass uuid; begin
 for r in select distinct on(user_id) id,user_id,expires_at from public.blink_vip_passes where auto_renew=true and expires_at<=now() and expires_at>now()-interval '2 hours' order by user_id,expires_at desc loop
   if exists(select 1 from public.blink_vip_passes n where n.user_id=r.user_id and n.starts_at>=r.expires_at and n.expires_at>r.expires_at) then continue; end if;
   insert into public.user_balances(user_id,spendable_coin_balance) values(r.user_id,0) on conflict(user_id) do nothing;
   select spendable_coin_balance into v_balance from public.user_balances where user_id=r.user_id for update;
   if v_balance>=v_price then
     update public.user_balances set spendable_coin_balance=spendable_coin_balance-v_price,updated_at=now() where user_id=r.user_id returning spendable_coin_balance into v_balance;
     v_pass:=private.activate_blink_vip_pass(r.user_id,null,null); update public.blink_vip_passes set auto_renew=true where id=v_pass;
     insert into public.blink_coin_transactions(user_id,kind,catalog_id,item_name,amount,balance_after) values(r.user_id,'VIP_AUTO_RENEW','blink_vip_10d','Blink VIP — 10 Days',-v_price,v_balance);
     insert into public.notifications(user_id,type,comment) values(r.user_id,'system','👑 Blink VIP renewed for another 10 days.');
   else
     update public.blink_vip_passes set auto_renew=false where id=r.id;
     insert into public.notifications(user_id,type,comment) values(r.user_id,'system','Blink VIP auto-renew could not complete because your Blink Coin balance is too low.');
   end if;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION public.gift_blink_vip(p_recipient_username text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid:=auth.uid(); v_recipient uuid; v_item public.blink_store_catalog%rowtype; v_price integer; v_balance bigint; v_inv uuid; begin
 if v_user is null then raise exception 'AUTHENTICATION_REQUIRED'; end if;
 select id into v_recipient from public.profiles where lower(username)=lower(trim(p_recipient_username)) limit 1; if v_recipient is null or v_recipient=v_user then raise exception 'INVALID_RECIPIENT'; end if;
 select * into v_item from public.blink_store_catalog where id='blink_vip_10d'; v_price:=private.blink_effective_price(v_user,v_item,1);
 insert into public.user_balances(user_id,spendable_coin_balance) values(v_user,0) on conflict(user_id) do nothing;
 select spendable_coin_balance into v_balance from public.user_balances where user_id=v_user for update; if v_balance<v_price then raise exception 'INSUFFICIENT_BLINK_COINS'; end if;
 update public.user_balances set spendable_coin_balance=spendable_coin_balance-v_price,updated_at=now() where user_id=v_user returning spendable_coin_balance into v_balance;
 insert into public.blink_inventory(user_id,catalog_id,quantity,status,gifted_by,metadata) values(v_recipient,'blink_vip_10d',1,'AVAILABLE',v_user,jsonb_build_object('gift',true)) returning id into v_inv;
 insert into public.blink_coin_transactions(user_id,kind,catalog_id,item_name,amount,balance_after,metadata) values(v_user,'VIP_GIFT','blink_vip_10d','Blink VIP — 10 Days gift',-v_price,v_balance,jsonb_build_object('recipient_id',v_recipient));
 insert into public.notifications(user_id,actor_id,type,comment) values(v_recipient,v_user,'system','👑 You received Blink VIP — 10 Days. Open Blink Store → Vault to activate it.');
 return jsonb_build_object('success',true,'balance',v_balance,'recipient_id',v_recipient,'inventory_id',v_inv);
end $function$

CREATE OR REPLACE FUNCTION public.record_game_session(p_game_type text, p_score integer, p_coins_earned integer DEFAULT 0)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_session_id uuid;
  v_score integer;
  v_coins integer;
  v_daily_points integer;
  v_game_type text := case lower(btrim(coalesce(p_game_type, '')))
    when 'trivia' then 'general_knowledge'
    when 'math' then 'math_sprint'
    when 'speed' then 'brain_mix'
    else lower(btrim(coalesce(p_game_type, '')))
  end;
begin
  if auth.uid() is null then
    raise exception 'AUTHENTICATION_REQUIRED';
  end if;
  if v_game_type not in (
    'brain_mix', 'math_sprint', 'logic', 'memory', 'word_power', 'general_knowledge'
  ) then
    raise exception 'INVALID_GAME_TYPE';
  end if;
  if p_score < 0 then
    raise exception 'INVALID_SCORE';
  end if;

  v_score := least(p_score, 500);
  v_coins := least(30, floor(v_score / 20.0)::integer);

  select coalesce(sum(score), 0)
  into v_daily_points
  from public.game_sessions
  where user_id = auth.uid()
    and started_at >= date_trunc('day', now());

  if v_daily_points + v_score > 5000 then
    raise exception 'DAILY_GAME_SCORE_LIMIT_REACHED';
  end if;

  if exists (
    select 1
    from public.game_sessions
    where user_id = auth.uid()
      and started_at > now() - interval '3 seconds'
  ) then
    raise exception 'GAME_SESSION_RATE_LIMITED';
  end if;

  insert into public.game_sessions(user_id, game_type, score, coins_earned, completed_at)
  values(auth.uid(), v_game_type, v_score, v_coins, now())
  returning id into v_session_id;

  insert into public.game_profiles(user_id, score, coins, updated_at)
  values(auth.uid(), v_score, v_coins, now())
  on conflict(user_id) do update set
    score = public.game_profiles.score + excluded.score,
    coins = public.game_profiles.coins + excluded.coins,
    updated_at = now();

  return v_session_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.send_blink_digital_gift(p_inventory_id uuid, p_recipient_username text, p_message text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user uuid := auth.uid();
  v_recipient uuid;
  v_recipient_username text;
  v_inv public.blink_inventory%rowtype;
  v_gift uuid;
  v_message text := nullif(btrim(coalesce(p_message,'')), '');
begin
  if v_user is null then raise exception 'AUTHENTICATION_REQUIRED'; end if;
  if p_recipient_username is null or btrim(p_recipient_username) = '' then raise exception 'RECIPIENT_REQUIRED'; end if;
  if v_message is not null and char_length(v_message) > 200 then raise exception 'MESSAGE_TOO_LONG'; end if;

  select p.id, p.username into v_recipient, v_recipient_username
  from public.profiles p
  where lower(p.username) = lower(regexp_replace(btrim(p_recipient_username), '^@', ''))
  limit 1;

  if v_recipient is null or v_recipient = v_user then raise exception 'INVALID_RECIPIENT'; end if;

  select * into v_inv
  from public.blink_inventory
  where id = p_inventory_id and user_id = v_user
  for update;

  if not found then raise exception 'INVENTORY_NOT_FOUND'; end if;
  if v_inv.catalog_id <> 'digital_gift' or v_inv.status <> 'AVAILABLE' or v_inv.quantity < 1 then
    raise exception 'DIGITAL_GIFT_NOT_AVAILABLE';
  end if;

  if v_inv.quantity > 1 then
    update public.blink_inventory
    set quantity = quantity - 1, updated_at = now()
    where id = v_inv.id;
  else
    update public.blink_inventory
    set status = 'USED', activated_at = now(), target_type = 'PROFILE', target_id = v_recipient, updated_at = now()
    where id = v_inv.id;
  end if;

  insert into public.blink_item_activations(user_id, inventory_id, catalog_id, target_type, target_id, started_at, metadata)
  values(v_user, v_inv.id, 'digital_gift', 'PROFILE', v_recipient, now(), jsonb_build_object('recipient_username', v_recipient_username));

  insert into public.blink_digital_gifts(sender_id, recipient_id, inventory_id, message)
  values(v_user, v_recipient, v_inv.id, v_message)
  returning id into v_gift;

  insert into public.notifications(user_id, actor_id, type, comment)
  values(v_recipient, v_user, 'system', coalesce('🎁 You received a Blink digital gift' || case when v_message is null then '.' else ': ' || v_message end, '🎁 You received a Blink digital gift.'));

  return jsonb_build_object(
    'success', true,
    'gift_id', v_gift,
    'recipient_id', v_recipient,
    'recipient_username', v_recipient_username
  );
end
$function$

CREATE OR REPLACE FUNCTION private.activate_blink_vip_pass(p_user uuid, p_inventory uuid, p_gifted_by uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_base timestamptz; v_pass uuid; v_auto boolean:=false; begin
  select greatest(now(),coalesce(max(expires_at),now())) into v_base from public.blink_vip_passes where user_id=p_user and expires_at>now();
  select coalesce((select auto_renew from public.blink_vip_passes where user_id=p_user order by expires_at desc limit 1),false) into v_auto;
  insert into public.blink_vip_passes(user_id,inventory_id,starts_at,expires_at,auto_renew,gifted_by) values(p_user,p_inventory,v_base,v_base+interval '10 days',v_auto,p_gifted_by) returning id into v_pass;
  insert into public.blink_vip_benefit_balances(pass_id,user_id) values(v_pass,p_user);
  update public.profiles set blink_vip_until=v_base+interval '10 days' where id=p_user;
  return v_pass;
end $function$

